import re
import os
from taf.ul.sc.util import util


class Commission:
    """Class for performing commissioning via EMS simulator"""

    def __init__(self, emssim, emssim_ws, path_to_commissioning_file, remote_dir='/tmp/commissionings/'):
        """
        Commission command.
        :param emssim: object to ta_moler Emssim class
        :param emssim_ws: object to moler UnixRemote class - server where EMS simulator is launched
        :param path_to_commissioning_file: local/remote path to commissioning file
        :param remote_dir: directory where file will be stored if use method
                           send_commissioning_file_to_emssim_workstation
        """

        self.path_to_commissioning_file = path_to_commissioning_file
        self.emssim = emssim
        self.emssim_ws = emssim_ws
        self.remote_dir = remote_dir

    def send_commissioning_file_to_emssim_workstation(self):
        """
        SCP commissioning file from UnixLocal to EMS workstation.
        :return:
        """
        util().upload_files(local_dir=os.path.dirname(self.path_to_commissioning_file),
                            local_file=os.path.basename(self.path_to_commissioning_file),
                            remote_dir=self.remote_dir,
                            remote_device_name=self.emssim_ws.name
                            )
        self.path_to_commissioning_file = os.path.join(self.remote_dir,
                                                       os.path.basename(self.path_to_commissioning_file))

    def perform_full_commissioning(self):
        """
        Performing full commissioning.
        :return:
        """
        plan_id = self._get_plan_id_from_commissioning_file()
        gzipped_cf = self._gzip_commissioning_file()
        self.emssim.run(cmd_name="file_download", cmd_params={'path': gzipped_cf,
                                                              'file_type': 12,
                                                              'plan_id': plan_id})
        self.emssim.run(cmd_name="activate_file", cmd_params={'file_type': 12,
                                                              'plan_id': plan_id})

    def _get_plan_id_from_commissioning_file(self):
        """
        Get Plan ID from commissioning file.
        :return: plan_id
        """
        re_plan_id = re.compile(r'id="(?P<PLAN_ID>\d+)"')
        plan_id = None

        results = self.emssim_ws.run(cmd_name="grep",
                                     cmd_params={'options': "'<cmData .*id=' {}".format(
                                         self.path_to_commissioning_file)})

        for line in results['LINES']:
            match = re_plan_id.search(line)
            if match:
                plan_id = match.group("PLAN_ID")
                break
        return plan_id

    def _gzip_commissioning_file(self):
        """
        gzip commissioning file
        :return: gzipped filename
        """
        gzip_cf = "{}.gz".format(self.path_to_commissioning_file)
        self.emssim_ws.run(cmd_name="gzip", cmd_params={'file_name': self.path_to_commissioning_file,
                                                        'compressed_file_name': gzip_cf})
        return gzip_cf
